const require_rpc = require('./rpc.cjs');

//#region src/types/interface.ts
function implement(contract, config) {
	const { handlers: perHandlerOpts,...serviceOptions } = config.options ?? {};
	const coreHandlers = {};
	for (const [name, desc] of Object.entries(contract._handlers)) {
		const fn = config.handlers[name];
		if (typeof fn !== "function") throw new Error(`implement(): missing handler "${name}"`);
		const sdkOpts = {
			input: desc._inputSerde,
			output: desc._outputSerde,
			description: desc._description,
			metadata: desc._metadata,
			...perHandlerOpts?.[name] ?? {}
		};
		if (contract._kind === "service") coreHandlers[name] = require_rpc.handlers.handler(sdkOpts, fn);
		else if (contract._kind === "object") coreHandlers[name] = desc._shared ? require_rpc.handlers.object.shared(sdkOpts, fn) : require_rpc.handlers.object.exclusive(sdkOpts, fn);
		else coreHandlers[name] = name === "run" ? require_rpc.handlers.workflow.workflow(sdkOpts, fn) : require_rpc.handlers.workflow.shared(sdkOpts, fn);
	}
	const common = {
		name: contract.name,
		handlers: coreHandlers,
		description: config.description ?? contract._description,
		metadata: config.metadata ?? contract._metadata,
		options: serviceOptions
	};
	const def = contract._kind === "service" ? require_rpc.service(common) : contract._kind === "object" ? require_rpc.object(common) : require_rpc.workflow(common);
	return Object.assign(def, {
		_kind: contract._kind,
		_handlers: contract._handlers
	});
}

//#endregion
exports.implement = implement;